import { parseProductSelection, type ProductSelection } from '../components/products/productSelectionValues';
import type { ProductDesignType } from '../components/products/productDesigns';

// This is a lookup contract, not a costing model. Every cell is generated by the canonical server calculator.
export const LANDING_PRICE_SCHEMA = 'landing-price-table.v1';
export const LANDING_PRICE_LEASE_MS = 30_000;
export const LANDING_PRICE_TYPES = ['pitched', 'gable', 'box-perimeter'] as const;
export const LANDING_PRICE_MATERIALS = ['acrylic', 'solid', 'combination'] as const;
export const LANDING_PRICE_WIDTHS = 86;
export const LANDING_PRICE_PROJECTIONS = 46;
export const LANDING_PRICE_CELLS = 3 * 3 * LANDING_PRICE_WIDTHS * LANDING_PRICE_PROJECTIONS;
export type LandingPriceTable = {
  schema: typeof LANDING_PRICE_SCHEMA; id: string; versionId: string; versionNumber: number; publicationKey: string;
  currency: 'NZD'; includesGst: true;
  /** Roofline, material, width (1500..10000), projection (1500..6000), in 100 mm steps. -1 unsupported; 0 tailored. */
  amounts: number[];
};
export type LandingDisplayPrice =
  | { status: 'priced'; amountIncGst: number }
  | { status: 'custom' | 'issue' | 'unavailable' | 'disabled' };
export type LandingPriceTableReply =
  | { status: 'ready'; table: LandingPriceTable; leaseMs: number }
  | { status: 'current'; id: string; leaseMs: number }
  | { status: 'disabled' | 'unavailable' };

export function landingPriceIndex(type: ProductDesignType, selection: ProductSelection): number | null {
  const parsed = parseProductSelection(selection);
  const roof = LANDING_PRICE_TYPES.indexOf(type), material = LANDING_PRICE_MATERIALS.indexOf(selection.material);
  if (!parsed || roof < 0 || material < 0 || parsed.sides !== 'open' || parsed.orientation !== 'parallel') return null;
  return ((roof * 3 + material) * LANDING_PRICE_WIDTHS + (parsed.widthMm - 1500) / 100)
    * LANDING_PRICE_PROJECTIONS + (parsed.projectionMm - 1500) / 100;
}

export function lookupLandingPrice(table: LandingPriceTable, type: ProductDesignType, selection: ProductSelection): LandingDisplayPrice | null {
  const index = landingPriceIndex(type, selection);
  if (index === null) return null;
  const amount = table.amounts[index];
  return amount === -1 ? { status: 'issue' } : amount === 0 ? { status: 'custom' } : { status: 'priced', amountIncGst: amount };
}

export function parseLandingPriceTable(value: unknown): LandingPriceTable | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const v = value as LandingPriceTable;
  if (v.schema !== LANDING_PRICE_SCHEMA || typeof v.id !== 'string' || !/^[a-f0-9]{64}$/.test(v.id)
    || typeof v.publicationKey !== 'string' || !/^[a-f0-9]{64}$/.test(v.publicationKey)
    || typeof v.versionId !== 'string' || !/^[a-f0-9-]{36}$/i.test(v.versionId)
    || !Number.isSafeInteger(v.versionNumber) || v.versionNumber < 1 || v.currency !== 'NZD' || v.includesGst !== true
    || !Array.isArray(v.amounts) || v.amounts.length !== LANDING_PRICE_CELLS
    || !v.amounts.every(n => Number.isSafeInteger(n) && n >= -1)) return null;
  return { schema: v.schema, id: v.id, versionId: v.versionId, versionNumber: v.versionNumber, publicationKey: v.publicationKey,
    currency: 'NZD', includesGst: true, amounts: v.amounts };
}
